from pathlib import Path
import sys, math
root=Path(sys.argv[1]);app=root/'public'/'app.js';cssp=root/'public'/'styles.css';a=app.read_text();css=cssp.read_text()
def bounds(name):
 s=[a.find(f'function {name}('),a.find(f'async function {name}(')];s=[x for x in s if x>=0]
 if not s: raise SystemExit('Função não encontrada: '+name)
 p=min(s);q=min([x for x in [a.find('\nfunction ',p+1),a.find('\nasync function ',p+1)] if x>=0] or [len(a)]);return p,q
def fn(name,code):
 global a;p,q=bounds(name);a=a[:p]+code+a[q:]
strategy=r'''function goalMonthIndex(iso){const [y,m]=String(iso||financeToday()).slice(0,7).split('-').map(Number);return y*12+(m||1)-1}
function goalStrategy(g){const target=Number(g.target_amount||0),current=Number(g.current_amount||0),remaining=Math.max(0,target-current);if(!target)return {done:false,avg:0,html:''};if(remaining<=0)return {done:true,avg:0,html:`<div class="goal-strategy done"><div class="goal-strategy-head"><span>${ic('check',15)}</span><div><strong>Meta alcançada</strong><small>Você chegou ao objetivo. 🎉</small></div></div></div>`};const today=financeToday(),all=state.data.goal_contributions.filter(c=>c.goal_id===g.id&&(!c.date||c.date<=today)),nowIdx=goalMonthIndex(today);let avg=0,monthsObserved=0;if(all.length){const firstIdx=Math.min(...all.map(c=>goalMonthIndex(c.date||today))),start=Math.max(firstIdx,nowIdx-5);monthsObserved=Math.max(1,nowIdx-start+1);const recent=all.filter(c=>goalMonthIndex(c.date||today)>=start);avg=recent.reduce((s,c)=>s+Number(c.amount||0),0)/monthsObserved}const deadlineIdx=g.deadline&&g.deadline>=today?goalMonthIndex(g.deadline):null,monthsToDeadline=deadlineIdx==null?null:Math.max(1,deadlineIdx-nowIdx+1),required=monthsToDeadline?remaining/monthsToDeadline:0,paceMonths=avg>0?Math.ceil(remaining/avg):null;let planMonthly=required||avg||remaining/12;if(!required&&avg>0)planMonthly=avg*1.2;planMonthly=Math.max(1,Math.ceil(planMonthly/10)*10);const weekly=Math.ceil((planMonthly/4.33)/5)*5,newMonths=Math.max(1,Math.ceil(remaining/planMonthly));let mainTitle='',mainText='';if(monthsToDeadline){if(avg<=0){mainTitle=`Mire ${money(planMonthly)} por mês`;mainText=`Nesse ritmo, a meta fica compatível com o prazo de ${dateBR(g.deadline)}.`}else if(avg+1<required){const gap=Math.max(0,required-avg);mainTitle=`Aumente cerca de ${money(Math.ceil(gap/10)*10)} por mês`;mainText=`Seu ritmo médio é ${money(Math.round(avg))}/mês. Para o prazo, o ideal é perto de ${money(Math.ceil(required/10)*10)}/mês.`}else{mainTitle='Você está no ritmo certo';mainText=`Sua média de ${money(Math.round(avg))}/mês já acompanha o prazo definido.`}}else if(avg>0){mainTitle=`Acelere para ${money(planMonthly)} por mês`;mainText=`Sua média recente é ${money(Math.round(avg))}/mês. Com cerca de 20% a mais, a estimativa cai para ${newMonths} mês(es).`}else{mainTitle=`Plano de 12 meses: ${money(planMonthly)}/mês`;mainText='Como ainda não há histórico suficiente, o Ritmo usa um plano inicial simples e ajusta conforme seus aportes.'}const joint=state.data.scope==='shared',split=joint?Math.ceil((planMonthly/2)/5)*5:0;return {done:false,avg,planMonthly,weekly,html:`<div class="goal-strategy"><div class="goal-strategy-head"><span>${ic('spark',15)}</span><div><strong>Estratégia do Ritmo</strong><small>Calculada com seus aportes reais</small></div></div><div class="goal-strategy-main"><strong>${mainTitle}</strong><p>${mainText}</p></div><div class="goal-strategy-tips"><div><span>${ic('calendar',13)}</span><div><strong>${money(weekly)}/semana</strong><small>quebra o próximo aporte em passos menores</small></div></div>${paceMonths?`<div><span>${ic('target',13)}</span><div><strong>${paceMonths} mês(es)</strong><small>estimativa no ritmo médio atual</small></div></div>`:''}${joint?`<div><span>${ic('users',13)}</span><div><strong>${money(split)} cada/mês</strong><small>se quiserem dividir o plano igualmente</small></div></div>`:''}</div></div>`}}
'''
# insert before goalCard
p,_=bounds('goalCard');a=a[:p]+strategy+a[p:]
fn('goalCard',r'''function goalCard(g){const pct=Math.min(100,Math.round((g.current_amount/g.target_amount)*100||0)),joint=state.data.scope==='shared',contribs=state.data.goal_contributions.filter(c=>c.goal_id===g.id),strategy=goalStrategy(g);return `<article class="goal-card"><div class="goal-head"><div><div class="goal-scope-badge ${joint?'joint':'solo'}">${joint?`${ic('users',12)} Juntos`:`${ic('user',12)} Individual`}</div><h3>${esc(g.name)}</h3><div class="meta">${esc(g.category)}${g.deadline?` • até ${dateBR(g.deadline)}`:''}${authorNote(g)}</div></div><span class="status ${pct>=100?'paid':'pending'}">${pct}%</span></div><div class="card-number">${money(g.current_amount)}</div><div class="card-sub">de ${money(g.target_amount)}</div><div class="progress"><i style="width:${pct}%"></i></div>${strategy.html}${joint&&contribs.length?`<div class="goal-contribs">${contribs.slice(0,4).map(c=>`<div><span><b>${esc((c.user_name||'Parceiro').split(' ')[0])}</b> • ${dateBR(c.date)}</span><strong>+ ${money(c.amount)}</strong></div>`).join('')}</div>`:''}<div class="debt-actions"><button class="btn btn-secondary" data-goal-add="${g.id}">Adicionar valor</button><button class="btn btn-secondary" data-edit="goal" data-id="${g.id}">Editar</button></div><div class="card-actions"><button class="mini-btn" data-delete="goal" data-id="${g.id}">${ic('trash',12)} Excluir meta</button></div></article>`}''')
app.write_text(a)
css+=r'''
.goal-strategy{margin-top:12px;padding:12px;border-radius:16px;background:color-mix(in srgb,var(--primary) 5%,var(--surface2));border:1px solid color-mix(in srgb,var(--primary) 9%,var(--line))}.goal-strategy-head{display:flex;align-items:center;gap:8px}.goal-strategy-head>span{width:30px;height:30px;border-radius:10px;display:grid;place-items:center;background:color-mix(in srgb,var(--gold) 14%,var(--surface-solid));color:var(--gold)}.goal-strategy-head strong,.goal-strategy-head small{display:block}.goal-strategy-head strong{font-size:10px}.goal-strategy-head small{font-size:8px;color:var(--muted)}.goal-strategy-main{padding:10px 0 8px}.goal-strategy-main>strong{font-size:11px}.goal-strategy-main p{margin:3px 0 0;color:var(--muted);font-size:9px;line-height:1.45}.goal-strategy-tips{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.goal-strategy-tips>div{display:flex;gap:6px;align-items:flex-start;padding:8px;border-radius:11px;background:var(--surface-solid);border:1px solid var(--line)}.goal-strategy-tips>div>span{color:var(--primary);flex:0 0 auto}.goal-strategy-tips strong,.goal-strategy-tips small{display:block}.goal-strategy-tips strong{font-size:9px}.goal-strategy-tips small{font-size:7.5px;line-height:1.35;color:var(--muted)}.goal-strategy.done{background:color-mix(in srgb,var(--sage) 8%,var(--surface2))}
@media(max-width:760px){.goal-strategy-tips{grid-template-columns:1fr}.goal-strategy{padding:11px}.goal-strategy-main{padding-bottom:7px}}
''';cssp.write_text(css)
print('Estratégia inteligente de metas aplicada.')
